INSERT INTO `books` VALUES ('532FHE','Book14','n/a','n/a',NULL,NULL,NULL,NULL),('DSADSA','Book12','Mark','the tehnics you need to know about driving',NULL,NULL,NULL,NULL),('ERYERF','Book6','n/a','n/a',NULL,NULL,NULL,NULL),('ERYG','Book4','John Doe','finding out who he is ',NULL,NULL,NULL,NULL),('FD3FDSF','Book10','Anna','n/a',NULL,NULL,NULL,NULL),('FDSF3','Book11','Kevin Lars','n/a',NULL,NULL,NULL,NULL),('FF4245G','testONE','ME','NOTHING',NULL,NULL,NULL,NULL),('FG435','Book5','Jane Doe','fixing up a broken chair',NULL,NULL,NULL,NULL),('GDFSG','Book7','Mark ','n/a',NULL,NULL,NULL,NULL),('OL15400582W','The Big Sleep','Raymond Chandler','Philip Marlowe, a private eye who operates in Los Angeles\'s seamy underside during the 1930s, takes on his first case, which involves a paralyzed California millionaire, two psychotic daughters, blackmail, and murder',NULL,'https://covers.openlibrary.org/b/id/7268475-M.jpg','2024-05-14 11:59:59','2024-05-14 11:59:59'),('OL239940W','कामसूत्र','Mallanaga Vātsyāyana','A work of philosophy, psychology, sociology, Hindu dogma, scientific inquiry, and sexology, the \"Kama Sutra\" has been a classic of world literature for more than 1700 years.',NULL,'https://covers.openlibrary.org/b/id/8003766-M.jpg','2024-05-09 13:18:06','2024-05-09 13:18:06'),('OL24034W','Treasure Island','Robert Louis Stevenson','Traditionally considered a coming-of-age story, Treasure Island is an adventure tale known for its atmosphere, characters and action, and also as a wry commentary on the ambiguity of morality — as seen in Long John Silver — unusual for children\'s literature then and now. It is one of the most frequently dramatized of all novels. The influence of Treasure Island on popular perceptions of pirates is enormous, including treasure maps marked with an \"X\", schooners, the Black Spot, tropical islands, and one-legged seamen carrying parrots on their shoulders',NULL,'https://covers.openlibrary.org/b/id/13859660-M.jpg','2024-05-09 15:08:33','2024-05-09 15:08:33'),('OL275946W','Black Boy','Richard Wright','Black Boy is a classic of American autobiography, a subtly crafted narrative of Richard Wright\'s journey from innocence to experience in the Jim Crow South. An enduring story of one young man\'s coming of age during a particular time and place, Black Boy remains a seminal text in our history about what it means to be a man, black, and Southern in America.',NULL,'https://covers.openlibrary.org/b/id/12707931-M.jpg','2024-05-14 11:39:36','2024-05-14 11:39:36'),('OL39108W','The Secret Agent','Joseph Conrad','**The Secret Agent: A Simple Tale** is a novel by Joseph Conrad, first published in 1907. The story is set in London in 1886 and deals with Mr. Adolf Verloc and his work as a spy for an unnamed country (presumably Russia). The Secret Agent is one of Conrad\'s later political novels in which he moved away from his former tales of seafaring. The novel is dedicated to H. G. Wells and deals broadly with anarchism, espionage, and terrorism. It also deals with exploitation of the vulnerable in Verloc\'s relationship with his brother-in-law Stevie, who has an intellectual disability. Conrad’s gloomy portrait of London depicted in the novel was influenced by Charles Dickens’ *Bleak House*.\r\n\r\n(Source: [Wikipedia](https://en.wikipedia.org/wiki/The_Secret_Agent))',NULL,'https://covers.openlibrary.org/b/id/8239401-M.jpg','2024-05-09 15:07:58','2024-05-09 15:07:58'),('OL4459213W','Bambi (First Colouring Tall)','Felix Salten','Describes the life of a deer in the forest as he grows into a beautiful stag.','Deer, Fiction, Juvenile fiction, Bambi (Fictitious character), Deer in fiction','https://covers.openlibrary.org/b/id/7153939-M.jpg','2024-05-15 12:09:49','2024-05-15 12:09:49'),('OL45310W','Robinson Crusoe','Daniel Defoe','The Life and Strange Surprising Adventures of Robinson Crusoe, Of York, Mariner: Who lived Eight and Twenty Years, all alone in an un-inhabited Island on the Coast of America, near the Mouth of the Great River of Oroonoque; Having been cast on Shore by Shipwreck, wherein all the Men perished but himself. With An Account how he was at last as strangely deliver\'d by Pyrates.','Robinson Cusoe, Imaginary Voyages, Fiction in Spanish, Toy and movable books, Pirates in fiction','https://covers.openlibrary.org/b/id/8783768-M.jpg','2024-05-15 12:09:36','2024-05-15 12:09:36'),('OL53959W','Life on the Mississippi','Mark Twain','At once a romantic history of a mighty river, an autobiographical account of Twains early steamboat days, and a storehouse of humorous anecdotes and sketches, here is the raw material from which Mark Twain wrote his finest novel, Adventures of Huckleberry Finn.','American Authors, Fiction, Historical Fiction, Juvenile literature, River boats','https://covers.openlibrary.org/b/id/9164717-M.jpg','2024-05-15 06:04:23','2024-05-15 06:04:23'),('OL55649W','Walden','Henry David Thoreau','Walden first published in 1854 as Walden; or, Life in the Woods) is a book by American transcendentalist writer Henry David Thoreau. The text is a reflection upon the author\'s simple living in natural surroundings. The work is part personal declaration of independence, social experiment, voyage of spiritual discovery, satire, and—to some degree—a manual for self-reliance.\r\n\r\nWalden details Thoreau\'s experiences over the course of two years, two months, and two days in a cabin he built near Walden Pond amidst woodland owned by his friend and mentor Ralph Waldo Emerson, near Concord, Massachusetts.\r\n\r\nThoreau makes precise scientific observations of nature as well as metaphorical and poetic uses of natural phenomena. He identifies many plants and animals by both their popular and scientific names, records in detail the color and clarity of different bodies of water, precisely dates and describes the freezing and thawing of the pond, and recounts his experiments to measure the depth and shape of the bottom of the supposedly \"bottomless\" Walden Pond.\r\n\r\n(Source: [Wikipedia](https://en.wikipedia.org/wiki/Walden))',NULL,'https://covers.openlibrary.org/b/id/11248037-M.jpg','2024-05-14 12:37:18','2024-05-14 12:37:18'),('OL5735363W','The Hunger Games','Suzanne Collins','The Hunger Games is a 2008 dystopian novel by the American writer Suzanne Collins. It is written in the perspective of 16-year-old Katniss Everdeen, who lives in the future, post-apocalyptic nation of Panem in North America. The Capitol, a highly advanced metropolis, exercises political control over the rest of the nation. The Hunger Games is an annual event in which one boy and one girl aged 12–18 from each of the twelve districts surrounding the Capitol are selected by lottery to compete in a televised battle royale to the death.\r\n\r\nThe book received critical acclaim from major reviewers and authors. It was praised for its plot and character development. In writing The Hunger Games, Collins drew upon Greek mythology, Roman gladiatorial games, and contemporary reality television for thematic content. The novel won many awards, including the California Young Reader Medal, and was named one of Publishers Weekly\'s \"Best Books of the Year\" in 2008.\r\n\r\nThe Hunger Games was first published in hardcover on September 14, 2008, by Scholastic, featuring a cover designed by Tim O\'Brien.',NULL,'https://covers.openlibrary.org/b/id/12646537-M.jpg','2024-05-10 04:43:06','2024-05-10 04:43:06'),('OL58402W','Guess How Much I Love You','Sam McBratney','Welcome the family classic with an elegant, refreshed cover — the quintessential picture book, just waiting to be shared.\r\n\r\nSometimes, when you love someone very, very much, you want to find a way of describing how much you treasure them. But, as Little Nutbrown Hare and Big Nutbrown Hare discover, love is not an easy thing to measure! For two decades, Sam McBratney’s timelessly endearing story, beautifully rendered in Anita Jeram’s exquisite watercolors, has captured the deep and tender bond between parent and child. Guess How Much I Love You is one of the world’s best-loved picture books.',NULL,'https://covers.openlibrary.org/b/id/13282906-M.jpg','2024-05-09 13:27:11','2024-05-09 13:27:11'),('OL61982W','Ὀδύσσεια','Όμηρος','The Odyssey (/ˈɒdəsi/; Greek: Ὀδύσσεια, Odýsseia) is one of two major ancient Greek epic poems attributed to Homer. It is, in part, a sequel to the Iliad, the other work ascribed to Homer. The poem is fundamental to the modern Western canon, and is the second oldest extant work of Western literature, the Iliad being the oldest. Scholars believe it was composed near the end of the 8th century BC, somewhere in Ionia, the Greek coastal region of Anatolia. - [Wikipedia][1]\r\n\r\n  [1]: https://en.wikipedia.org/wiki/Odyssey',NULL,'https://covers.openlibrary.org/b/id/9045853-M.jpg','2024-05-09 13:57:47','2024-05-09 13:57:47'),('OL69181W','Narrative of the life of Frederick Douglass, an American slave','Frederick Douglass','Published in 1845, this pre-eminent American slave narrative powerfully details the life of the internationally famous abolitionist Frederick Douglass from his birth into slavery in 1818 to his escape to the North in 1838—how he endured the daily physical and spiritual brutalities of his owners and drivers, how he learned to read and write, and how he grew into a man who could only live free or die.','Biography, Abolitionists, African American abolitionists, Slaves, Slavery','https://covers.openlibrary.org/b/id/6630144-M.jpg','2024-05-15 12:09:27','2024-05-15 12:09:27'),('OL81294W','Women in Love','David Herbert Lawrence','Dark, but filled with bright genius, Women in Love is a prophetic masterpiece steeped in eroticism, filled with perceptions about sexual power and obsession that have proven to be timeless and true.',NULL,'https://covers.openlibrary.org/b/id/13140934-M.jpg','2024-05-09 13:27:30','2024-05-09 13:27:30'),('REWHFD','test2','John','about his life',NULL,NULL,NULL,NULL),('RR','Book13','Fred Low','n/a',NULL,NULL,NULL,NULL),('RWHS','finding nemo','Nemo','about my journey',NULL,NULL,NULL,NULL),('TEW35','Book9','Oliver','n/a',NULL,NULL,NULL,NULL),('Y3W4GDF','Book8','Steven Williams','n/a',NULL,NULL,NULL,NULL);
